-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/jeuno/The_Old_Monument.lua"]={["Path"]="scripts/quests/jeuno/The_Old_Monument.lua",["SHA256"]="4f0316dd19bafc927159e61bc4ebbe3da1bc7b4c162323b0275ac4530352c96e",["Text"]="-----------------------------------\n-- The Old Monument\n-----------------------------------\n-- Log ID: 3, Quest ID: 11\n-- Mertaire    : !pos -17 0 -61 245\n-- Bki Tbujhja : !pos -22 0 -60 245\n-- Song Runes  : !pos -244 16 -280 118\n-----------------------------------\nlocal buburimuID   = zones[xi.zone.BUBURIMU_PENINSULA]\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_OLD_MONUMENT)\n\nquest.reward =\n{\n    item  = xi.item.POETIC_PARCHMENT,\n    title = xi.title.RESEARCHER_OF_CLASSICS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n\n            ['Mataligeat'] = quest:event(140),\n\n            ['Mertaire'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(102)\n                    else\n                        return quest:messageName(lowerJeunoID.text.MERTAIRE_MALLIEBELL_LEFT, 0, 0, 0, 0, true, false)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [102] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.BUBURIMU_PENINSULA] =\n        {\n            ['Song_Runes'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeHasExactly(trade, xi.item.SHEET_OF_PARCHMENT)\n                    then\n                        return quest:progressCutscene(2)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    if questProgress == 1 then\n                        return quest:progressCutscene(0)\n                    elseif questProgress == 2 then\n                        return quest:messageSpecial(buburimuID.text.SONG_RUNES_REQUIRE, xi.item.SHEET_OF_PARCHMENT)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [2] = function(player, csid, option, npc)\n                    player:messageSpecial(buburimuID.text.SONG_RUNES_WRITING, xi.item.SHEET_OF_PARCHMENT)\n\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/The_Requiem.lua"]={["Path"]="scripts/quests/jeuno/The_Requiem.lua",["SHA256"]="aa89cdd9992527b15431e7842c6adbb1e7cce4e30d7b7d7198ef1c7b670bb9ca",["Text"]="-----------------------------------\n-- The Requiem\n-----------------------------------\n-- Log ID: 3, Quest ID: 64\n-- !addquest 3 64\n-- Bki Tbujhja : !pos -22 0 -60 245\n-- Mataligeat  : !pos -24 0 -60 245\n-- Sarcophagus : !pos -421 6.5 503 195\n-----------------------------------\n-- The bard's sarcophagus is fixed: the fourth of the five in the crypt room (first ID + 3).\n-- Trading the flask of holy water to any other sarcophagus does nothing.\n-----------------------------------\nlocal ID = zones[xi.zone.THE_ELDIEME_NECROPOLIS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_REQUIEM)\n\nquest.reward =\n{\n    item = xi.item.CHORAL_SLIPPERS,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.PAINFUL_MEMORY) and\n                player:getMainJob() == xi.job.BRD and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Bki_Tbujhja'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(145)\n                    else\n                        return quest:progressEvent(148) -- Short offer after the player declined once.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [145] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    elseif option == 0 then\n                        quest:setVar(player, 'Option', 1) -- Player declined.\n                    end\n                end,\n\n                [148] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Bki_Tbujhja'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        npcUtil.tradeMatches(trade, { { xi.item.FLASK_OF_HOLY_WATER, 1 } })\n                    then\n                        return quest:progressEvent(151) -- Bki blesses the flask and hands it back.\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.STAR_RING1) then\n                        return quest:progressEvent(150)\n                    elseif quest:getVar(player, 'Prog') == 0 then\n                        return quest:event(146)\n                    elseif math.randomInt(1, 100) <= 50 then\n                        return quest:event(147)\n                    else\n                        return quest:event(149)\n                    end\n                end,\n            },\n\n            ['Mataligeat'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') >= 1 and\n                        not player:hasKeyItem(xi.keyItem.STAR_RING1)\n                    then\n                        return quest:event(142)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [150] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                    end\n                end,\n\n                [151] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS] =\n        {\n            ['Sarcophagus'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npc:getID() == ID.npc.SARCOPHAGUS_OFFSET + 3 and\n                        quest:getVar(player, 'Prog') == 1 and\n                        quest:getVar(player, 'Popped') == 0 and\n                        npcUtil.tradeMatches(trade, { { xi.item.FLASK_OF_HOLY_WATER, 1 } }) and\n                        npcUtil.popFromQM(player, npc, { ID.mob.YUM_KIMIL, ID.mob.YUM_KIMIL + 1, ID.mob.YUM_KIMIL + 2 }, { hide = 0 })\n                    then\n                        player:tradeComplete()\n                        quest:setVar(player, 'Popped', 1)\n                        return quest:noAction() -- No message. The guardians spawn and immediately aggro.\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if npc:getID() ~= ID.npc.SARCOPHAGUS_OFFSET + 3 then\n                        return\n                    end\n\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(46)\n                    elseif\n                        quest:getVar(player, 'Prog') == 1 and\n                        quest:getVar(player, 'Popped') == 1 and\n                        npcUtil.popFromQM(player, npc, { ID.mob.YUM_KIMIL, ID.mob.YUM_KIMIL + 1, ID.mob.YUM_KIMIL + 2 }, { hide = 0 })\n                    then\n                        return quest:noAction() -- Repop after a wipe. No message.\n                    end\n                end,\n            },\n\n            ['Yum_Kimil'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [46] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.STAR_RING1) -- Kept after completion. The Circle of Time consumes it.\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Bki_Tbujhja'] = quest:event(134):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/The_Road_to_Aht_Urhgan.lua"]={["Path"]="scripts/quests/jeuno/The_Road_to_Aht_Urhgan.lua",["SHA256"]="7072f9959630d26fd33e9f29d9bd2941204ff0e9072480b88e4acc3ed0d7994a",["Text"]="-----------------------------------\n-- The Road to Aht Urhgan\n-----------------------------------\n-- Log ID: 3, Quest ID: 91\n-- Faursel : !pos 37.985 3.118 -45.208 245\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_ROAD_TO_AHT_URHGAN)\n\nquest.reward =\n{\n}\n\nlocal beginnerList =\n{\n    { xi.item.DAMSELFLY_WORM,        1 },\n    { xi.item.MAGICKED_SKULL,        1 },\n    { xi.item.CRAB_APRON,            1 },\n    { xi.item.BLOODY_ROBE,           1 },\n    { xi.item.CUP_OF_DHALMEL_SALIVA, 1 },\n    { xi.item.WILD_RABBIT_TAIL,      1 },\n}\n\nlocal intermediateList =\n{\n    { xi.item.JADE_CRYPTEX,        1 },\n    { xi.item.SILVER_ENGRAVING,    1 },\n    { xi.item.THIRTEEN_KNOT_QUIPU, 1 },\n}\n\nlocal chipList =\n{\n    { xi.item.CARMINE_CHIP, 1 },\n    { xi.item.CYAN_CHIP,    1 },\n    { xi.item.GRAY_CHIP,    1 },\n}\n\nlocal advancedSingleList =\n{\n    xi.item.DAVOI_COFFER_KEY,\n    xi.item.BEADEAUX_COFFER_KEY,\n    xi.item.OZTROJA_COFFER_KEY,\n    xi.item.UGGALEPIH_COFFER_KEY,\n    xi.item.RANCOR_DEN_COFFER_KEY,\n    xi.item.QUICKSAND_COFFER_KEY,\n    xi.item.GROTTO_COFFER_KEY,\n    xi.item.WARRIORS_TESTIMONY,\n    xi.item.MONKS_TESTIMONY,\n    xi.item.WHITE_MAGES_TESTIMONY,\n    xi.item.BLACK_MAGES_TESTIMONY,\n    xi.item.RED_MAGES_TESTIMONY,\n    xi.item.THIEFS_TESTIMONY,\n    xi.item.PALADINS_TESTIMONY,\n    xi.item.DARK_KNIGHTS_TESTIMONY,\n    xi.item.BEASTMASTERS_TESTIMONY,\n    xi.item.BARDS_TESTIMONY,\n    xi.item.RANGERS_TESTIMONY,\n    xi.item.SAMURAIS_TESTIMONY,\n    xi.item.NINJAS_TESTIMONY,\n    xi.item.DRAGOONS_TESTIMONY,\n    xi.item.SUMMONERS_TESTIMONY,\n    xi.item.BLUE_MAGES_TESTIMONY,\n    xi.item.CORSAIRS_TESTIMONY,\n    xi.item.PUPPETMASTERS_TESTIMONY,\n    xi.item.DANCERS_TESTIMONY,\n    xi.item.SCHOLARS_TESTIMONY,\n}\n\nlocal function handleEventUpdate(player, csid, option, npc)\n    if option == 10 then\n        player:updateEvent(xi.item.DAMSELFLY_WORM, xi.item.MAGICKED_SKULL, xi.item.CRAB_APRON, xi.item.BLOODY_ROBE, xi.item.CUP_OF_DHALMEL_SALIVA, xi.item.WILD_RABBIT_TAIL, 0, 0)\n    elseif option == 12 then\n        player:updateEvent(xi.item.JADE_CRYPTEX, xi.item.SILVER_ENGRAVING, xi.item.THIRTEEN_KNOT_QUIPU, 0, 0, 0, 0, 0)\n    elseif option == 13 then\n        player:updateEvent(xi.item.CARMINE_CHIP, xi.item.CYAN_CHIP, xi.item.GRAY_CHIP, 0, 0, 0, 0, 0)\n    elseif option == 14 then\n        player:updateEvent(1, 1, 1, 1, 1, 1, player:getGil(), 1)\n    end\nend\n\nlocal function handleSelectionEventFinish(player, csid, option, npc)\n    -- Where's Tenzen?\n    if\n        option == 1 and\n        player:getCurrentMission(xi.mission.log_id.ROV) == xi.mission.id.rov.INESCAPABLE_BINDS\n    then\n        if quest:complete(player) then\n            npcUtil.giveKeyItem(player, xi.keyItem.BOARDING_PERMIT)\n            npcUtil.completeMission(player, xi.mission.log_id.ROV, xi.mission.id.rov.INESCAPABLE_BINDS, { nextMission = { xi.mission.log_id.ROV, xi.mission.id.rov.DESERT_WINDS } })\n        end\n    -- Let me think about it.\n    elseif option == 2 then\n        quest:setVar(player, 'Prog', 1)\n\n    -- Purchase Boarding Permit with Gil\n    elseif option == 3 then\n        if player:getGil() >= 500000 then\n            player:delGil(500000)\n            player:messageSpecial(zones[xi.zone.LOWER_JEUNO].text.PAY_FAURSEL, 500000)\n            quest:setVar(player, 'Prog', 2)\n            quest:setMustZone(player)\n            quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n        end\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.settings.main.ENABLE_TOAU == 1\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Faursel'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(10062)\n                    end\n\n                    return quest:progressEvent(10063, 0, 0, 0, 0, 0, player:getCurrentMission(xi.mission.log_id.ROV) == xi.mission.id.rov.INESCAPABLE_BINDS and 1 or 0)\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [10063] = handleEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                -- Hearing Faursel out grants nothing. The quest is only added to the log when 10063 ends on a selection.\n                [10062] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [10063] = function(player, csid, option, npc)\n                    if option == 2 or option == 3 then\n                        quest:begin(player)\n                    end\n\n                    handleSelectionEventFinish(player, csid, option, npc)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Faursel'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        (\n                            npcUtil.tradeMatches(trade, beginnerList) or\n                            npcUtil.tradeMatches(trade, intermediateList) or\n                            npcUtil.tradeMatches(trade, chipList) or\n                            npcUtil.tradeSetInList(trade, advancedSingleList)\n                        )\n                    then\n                        return quest:progressEvent(10069)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    local timePassed    = quest:getVar(player, 'Timer') <= VanadielUniqueDay() and not quest:getMustZone(player)\n\n                    -- No decision yet. Faursel reads the lists again.\n                    -- Prog 0: accepted back when 10062 granted the quest.\n                    if questProgress == 0 or questProgress == 1 then\n                        return quest:progressEvent(10064, 0, 0, 0, 0, 0, player:getCurrentMission(xi.mission.log_id.ROV) == xi.mission.id.rov.INESCAPABLE_BINDS and 1 or 0)\n\n                    -- Purchased the Boarding Permit\n                    elseif questProgress == 2 then\n                        if timePassed then\n                            -- Capture: the parameters 10067 starts with. Zeros end the cutscene before the fade to black.\n                            return quest:progressEvent(10067, 15, 1, 3, -1, 541, 540, 0, 99)\n                        else\n                            return quest:event(10066) -- No refunds. Come back tomorrow.\n                        end\n\n                    -- Traded Items for Boarding Permit\n                    elseif questProgress == 3 then\n                        if timePassed then\n                            return quest:progressEvent(10070)\n                        else\n                            return quest:event(10072) -- Come back tomorrow.\n                        end\n\n                    -- Purchased Permit, and has returned from Wajaom Woodlands\n                    elseif questProgress == 5 then\n                        return quest:progressEvent(10068)\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [10064] = handleEventUpdate,\n\n                -- Capture: the reply to the option 30 update. The cutscene shows the key items and holds the black screen for the warp.\n                [10067] = function(player, csid, option, npc)\n                    if option == 30 then\n                        player:updateEvent(79, 1, 0, 34, 910, 540, 99, 99)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10064] = handleSelectionEventFinish,\n\n                [10067] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                    xi.teleport.to(player, xi.teleport.id.WAJAOM_LEYPOINT)\n                end,\n\n                [10068] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [10069] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setMustZone(player)\n                    quest:setVar(player, 'Prog', 3)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                end,\n\n                [10070] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        npcUtil.giveKeyItem(player, xi.keyItem.BOARDING_PERMIT)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            afterZoneIn = function(player)\n                -- Player won't see these messages due to teleporting at the end of the cutscene if awarded then. Display after they zone in.\n                -- NOTE: Prog value of 4 is set immediately before teleporting the player.\n                if quest:getVar(player, 'Prog') == 4 then\n                    npcUtil.giveKeyItem(player, xi.keyItem.BOARDING_PERMIT)\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_OF_WAJAOM_WOODLANDS)\n                    quest:setVar(player, 'Prog', 5)\n                end\n            end,\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Faursel'] = quest:event(10071):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Unlisted_Qualities.lua"]={["Path"]="scripts/quests/jeuno/Unlisted_Qualities.lua",["SHA256"]="5c411982e17411f73d49bcea172e512669f3757a6bb7093855101bc343cb75f7",["Text"]="-----------------------------------\n-- Unlisted Qualities\n-----------------------------------\n-- Log ID: 3, Quest ID: 77\n-- Luto Mewrilah: !pos -52 0 46 244\n-- Red Ghost:     !pos -99 0 0 246\n-- Akta:          !pos 6 0 -68.6 243\n-- Kuah Dakonsa:  !pos -40 0 -65 245\n-- Bheem:         !pos -89 0 168 244\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.UNLISTED_QUALITIES)\n\n-- Packs Fellow properties into a single integer, as expected by events.\n-- 0000 0000 FFFF SS00 00PP PP00 0RRR NNNN\n-- Face, Size, Personality, Race, Name\nlocal function packData(name, race, pers, face, size)\n    return bit.bor(\n        name,\n        bit.lshift(race, 4),\n        bit.lshift(pers >= 1 and pers or 0, 10),\n        bit.lshift(size >= 1 and size or 0, 18),\n        bit.lshift(face >= 0 and face or 15, 20)\n    )\nend\n\nlocal function unpackData(packed)\n    local rawPers = bit.band(bit.rshift(packed, 10), 0x0F)\n    local rawSize = bit.band(bit.rshift(packed, 18), 0x03)\n    local rawFace = bit.band(bit.rshift(packed, 20), 0x0F)\n\n    return\n    {\n        name = bit.band(packed, 0x0F),\n        race = bit.band(bit.rshift(packed, 4), 0x07),\n        pers = rawPers >= 1 and rawPers or -1,\n        size = rawSize >= 1 and rawSize or -1,\n        face = rawFace < 15 and rawFace or -1,\n    }\nend\n\n-- Check if all 3 NPC info gathered, advance to Bheem phase\nlocal function checkAdvanceToPhase1(player)\n    local d = unpackData(quest:getVar(player, 'Data'))\n    if d.pers >= 1 and d.face >= 0 and d.size >= 1 then\n        quest:setVar(player, 'Prog', 1)\n    end\nend\n\nquest.sections =\n{\n    -- Quest start: Talk to Luto, select name/race\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Luto_Mewrilah'] = quest:event(10031):importantOnce(),\n\n            onEventFinish =\n            {\n                [10031] = function(player, csid, option, npc)\n                    if option == utils.EVENT_CANCELLED_OPTION then\n                        return\n                    end\n\n                    -- Parse race and name from option (0-indexed)\n                    local name = bit.band(option, 0x0F)\n                    local race = bit.band(bit.rshift(option, 4), 0x07)\n\n                    -- 8 races, 8 names per race.\n                    if race > 7 or name > 7 then\n                        return\n                    end\n\n                    quest:begin(player)\n                    quest:setVar(player, 'Data', packData(name, race, -1, -1, -1))\n                end,\n            },\n        },\n    },\n\n    -- Prog 0: Gather info from NPCs (size, face, personality)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Luto_Mewrilah'] = quest:event(10033),\n            ['Bheem']         = quest:event(10037):oncePerZone(),\n        },\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Akta'] =\n            {\n                onTrigger = function(player, npc)\n                    local data = quest:getVar(player, 'Data')\n                    local d    = unpackData(data)\n\n                    if d.size == -1 then\n                        return quest:event(10103, { [7] = data })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10103] = function(player, csid, option, npc)\n                    -- 1 = Small, 2 = Average Height, 3 = Pretty Tall\n                    if option < 1 or option > 3 then\n                        return\n                    end\n\n                    local d = unpackData(quest:getVar(player, 'Data'))\n                    quest:setVar(player, 'Data', packData(d.name, d.race, d.pers, d.face, option))\n                    checkAdvanceToPhase1(player)\n                end,\n            },\n        },\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Kuah_Dakonsa'] =\n            {\n                onTrigger = function(player, npc)\n                    local data = quest:getVar(player, 'Data')\n                    local d    = unpackData(data)\n\n                    if d.face == -1 then\n                        return quest:event(20000, { [7] = data })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [20000] = function(player, csid, option, npc)\n                    -- Event returns 0-15 for faces 1A-8B\n                    if option < 0 or option > 15 then\n                        return\n                    end\n\n                    local d = unpackData(quest:getVar(player, 'Data'))\n                    quest:setVar(player, 'Data', packData(d.name, d.race, d.pers, option, d.size))\n                    checkAdvanceToPhase1(player)\n                end,\n            },\n        },\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Red_Ghost'] =\n            {\n                onTrigger = function(player, npc)\n                    local data = quest:getVar(player, 'Data')\n                    local d    = unpackData(data)\n\n                    if d.pers == -1 then\n                        return quest:event(320, { [7] = data })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [320] = function(player, csid, option, npc)\n                    if option < 0 and option > 11 then\n                        return\n                    end\n\n                    local d           = unpackData(quest:getVar(player, 'Data'))\n                    -- Race is 0-indexed here (unlike xi.race enum)\n                    local isFemale    = (d.race % 2 == 1 and d.race ~= 7) or d.race == 6\n\n                    -- Red Ghost returns 0-5 for male, 6-11 for female\n                    local validMale   = option >= 0 and option <= 5\n                    local validFemale = option >= 6 and option <= 11\n\n                    if (isFemale and validFemale) or (not isFemale and validMale) then\n                        -- This gets stored as +1 as Bheem expects it 1-indexed.\n                        quest:setVar(player, 'Data', packData(d.name, d.race, option + 1, d.face, d.size))\n                        checkAdvanceToPhase1(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Prog 1: Talk to Bheem after gathering all info\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Bheem'] =\n            {\n                onTrigger = function(player, npc)\n                    local data = quest:getVar(player, 'Data')\n                    return quest:event(10171, { [7] = data })\n                end,\n\n                onEventUpdate = function(player, csid, option, npc)\n                    local data = quest:getVar(player, 'Data')\n                    player:updateEvent({ [7] = data })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10171] = function(player, csid, option, npc)\n                    if option == utils.EVENT_CANCELLED_OPTION then\n                        return\n                    end\n\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Prog 2: Return to Luto Mewrilah to complete\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Luto_Mewrilah'] = quest:progressEvent(10032),\n\n            -- TODO: Quest completion disabled until core changes made to save Fellows\n            -- onEventFinish =\n            -- {\n            --     [10032] = function(player, csid, option, npc)\n            --         if option == 0 and npcUtil.giveItem(player, xi.item.SILVER_INGOT) then\n            --             quest:complete(player)\n            --         end\n            --     end,\n            -- },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Unlocking_A_Myth_BLM.lua"]={["Path"]="scripts/quests/jeuno/Unlocking_A_Myth_BLM.lua",["SHA256"]="14f09a884d3023b06ae7f8e20e4cba5af18a4833fe5b3898ce56819b07d98a16",["Text"]="-----------------------------------\n-- Unlocking a Myth: Black Mage\n-----------------------------